"use strict";
module.exports = "<div class=\"dialog-mdsd-main\">\r\n    <h1 mat-dialog-title class=\"dialog-title\" mat-dialog-draggable>{{'dlg.menuitem-title' | translate}}</h1>\r\n    <mat-icon (click)=\"onNoClick()\" class=\"dialog-close-btn\">clear</mat-icon>\r\n    <div mat-dialog-content class=\"dialog-mdsd-content content\">\r\n        <div class=\"my-form-field block mb10\">\r\n            <span>{{'dlg.menuitem-icon' | translate}}</span>\r\n            <mat-select [(value)]=\"data.item.icon\"\r\n                        panelClass=\"icon-grid-panel\"\r\n                        panelWidth=\"310px\"\r\n                        style=\"width: 60px; height: 40px\"\r\n                        #iconsel>\r\n                <mat-select-trigger>\r\n                    <mat-icon>{{iconsel.value}}</mat-icon>\r\n                </mat-select-trigger>\r\n                <mat-option [value]=\"'image'\" (click)=\"imagefile.value = '';imagefile.click();\">\r\n                    {{'dlg.menuitem-image' | translate}}\r\n                    <input #imagefile type=\"file\" style=\"display: none;\" (change)=\"onSetImage($event)\" accept=\"image/png|jpg|svg\" />\r\n                </mat-option>\r\n                <mat-option>\r\n                    <div class=\"my-form-field\">\r\n                        <input\r\n                            matInput\r\n                            [(ngModel)]=\"filterText\"\r\n                            (input)=\"onFilterChange()\"\r\n                            (click)=\"$event.stopPropagation()\"\r\n                            (keydown)=\"$event.stopPropagation()\"\r\n                            placeholder=\"{{'dlg.menuitem-icons-filter' | translate}}\"\r\n                            type=\"text\"\r\n                            autocomplete=\"off\"/>\r\n                    </div>\r\n                </mat-option>\r\n                <mat-option *ngFor=\"let icon of filteredIcons$ | async\" [value]=\"icon\" (click)=\"data.item.image = ''\" style=\"display: inline-block !important; width: 18px;\">\r\n                    <mat-icon class=\"\">{{ icon }}</mat-icon>\r\n                </mat-option>\r\n            </mat-select>\r\n        </div>\r\n        <div class=\"my-form-field block mb10\" style=\"min-width: 300px;\">\r\n            <span>{{'dlg.menuitem-text' | translate}}</span>\r\n            <input [(ngModel)]=\"data.item.text\" type=\"text\" style=\"width: calc(100% - 7px)\">\r\n        </div>\r\n        <div class=\"my-form-field block mb10\">\r\n            <span>{{'dlg.menuitem-view' | translate}}</span>\r\n            <mat-select [(value)]=\"data.item.view\">\r\n                <mat-option *ngFor=\"let view of data.views\" [value]=\"view.id\">\r\n                    {{ view.name }}\r\n                </mat-option>\r\n                <mat-option [value]=\"linkAddress\">[{{'dlg.menuitem-link' | translate}}]</mat-option>\r\n                <mat-option [value]=\"linkAlarms\">[{{'dlg.menuitem-alarms' | translate}}]</mat-option>\r\n                <!-- <mat-option [value]=\"events\">[{{'dlg.menuitem-events' | translate}}]</mat-option> -->\r\n            </mat-select>\r\n        </div>\r\n        <div *ngIf=\"data.item.view === '[link]'\" class=\"my-form-field block mb10\">\r\n            <span>{{'dlg.menuitem-address' | translate}}</span>\r\n            <input [(ngModel)]=\"data.item.link\" type=\"text\" style=\"width: 300px\">\r\n        </div>\r\n        <div class=\"my-form-field block mb10\">\r\n            <span>{{'dlg.useraccess-groups' | translate}}</span>\r\n            <sel-options #seloptions [selected]=\"selected\" [options]=\"options\"></sel-options>\r\n        </div>\r\n        <!-- Submeu -->\r\n        <div class=\"my-form-field block mb10 submenu-header\">\r\n            <button mat-icon-button (click)=\"onAddChild()\">\r\n                <mat-icon aria-label=\"Add\">control_point</mat-icon>\r\n            </button>\r\n            <span>{{'dlg.menuitem-add-submenu' | translate}}</span>\r\n        </div>\r\n        <!-- List submenu -->\r\n        <div *ngIf=\"data.item.children?.length\" style=\"max-height: 200px;\">\r\n            <div *ngFor=\"let child of data.item.children; let i = index\" class=\"submenu-item\">\r\n                <div class=\"my-form-field inbk mr10\">\r\n                    <span>{{'dlg.menuitem-text' | translate}}</span>\r\n                    <input [(ngModel)]=\"child.text\" type=\"text\" style=\"width: 200px\">\r\n                </div>\r\n                <div class=\"my-form-field inbk mr10\">\r\n                    <span>{{'dlg.menuitem-view' | translate}}</span>\r\n                    <mat-select [(value)]=\"child.view\" style=\"width: 200px\">\r\n                        <mat-option *ngFor=\"let view of data.views\" [value]=\"view.id\">\r\n                            {{ view.name }}\r\n                        </mat-option>\r\n                        <mat-option [value]=\"linkAddress\">[{{'dlg.menuitem-link' | translate}}]</mat-option>\r\n                        <mat-option [value]=\"linkAlarms\">[{{'dlg.menuitem-alarms' | translate}}]</mat-option>\r\n                    </mat-select>\r\n                </div>\r\n                <div *ngIf=\"child.view === '[link]'\" class=\"my-form-field inbk mr10\">\r\n                    <span>{{'dlg.menuitem-address' | translate}}</span>\r\n                    <input [(ngModel)]=\"child.link\" type=\"text\" style=\"width: 200px\">\r\n                </div>\r\n                <button mat-icon-button (click)=\"onDeleteChild(i)\">\r\n                    <mat-icon>clear</mat-icon>\r\n                </button>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div mat-dialog-actions class=\"dialog-action\">\r\n        <button mat-raised-button (click)=\"onNoClick()\">{{'dlg.cancel' | translate}}</button>\r\n        <button mat-raised-button color=\"primary\" (click)=\"onOkClick()\" cdkFocusInitial>{{'dlg.ok' | translate}}</button>\r\n    </div>\r\n</div>";

