module.exports = "<form [formGroup]=\"formGroup\"\r\n      class=\"container\">\r\n    <h1 mat-dialog-title class=\"dialog-title\" mat-dialog-draggable>{{'notification.property-title' | translate}}</h1>\r\n    <mat-icon (click)=\"onNoClick()\" class=\"dialog-close-btn\">clear</mat-icon>\r\n    <div mat-dialog-content class=\"dialog-content\">\r\n        <div class=\"my-form-field item-block\">\r\n            <span>*{{'notification.property-name' | translate}}</span>\r\n            <input formControlName=\"name\" type=\"text\">\r\n        </div>\r\n        <div class=\"my-form-field item-block mt10\">\r\n            <span>*{{'notification.property-receiver' | translate}}</span>\r\n            <input formControlName=\"receiver\" type=\"text\">\r\n        </div>\r\n        <div class=\"block mt10\">\r\n            <div class=\"my-form-field\">\r\n                <span>*{{'notification.property-type' | translate}}</span>\r\n                <mat-select formControlName=\"type\" (selectionChange)=\"onTypeChanged($event.value)\" style=\"width: 207px\">\r\n                    <mat-option [value]=\"\"> </mat-option>\r\n                    <mat-option value=\"scenes\">八场景事件</mat-option>\r\n                    <mat-option [value]=\"notificationAlarm\"> {{ notificationsType[notificationAlarm] }} </mat-option>\r\n                    <mat-option [value]=\"notificationAccess\"> {{ notificationsType[notificationAccess] }} </mat-option>\r\n                </mat-select>\r\n            </div>\r\n            <div class=\"my-form-field ml15\" *ngIf=\"formGroup.value.type === notificationAlarm\">\r\n                <span>{{'notification.property-delay' | translate}}</span>\r\n                <input numberOnly formControlName=\"delay\" type=\"number\" max=\"60\" min=\"1\" step=\"1\" style=\"width:80px\">\r\n            </div>\r\n            <div class=\"my-form-field ml15\" *ngIf=\"formGroup.value.type === notificationAlarm\">\r\n                <span>{{'notification.property-interval' | translate}}</span>\r\n                <input numberOnly formControlName=\"interval\" type=\"number\" max=\"60\" min=\"0\" step=\"1\" style=\"width:80px\">\r\n            </div>\r\n            <div class=\"my-form-field ml20\">\r\n                <span>{{'notification.property-enabled' | translate}}</span>\r\n                <mat-slide-toggle color=\"primary\" formControlName=\"enabled\" style=\"vertical-align: middle;\"></mat-slide-toggle>\r\n            </div>\r\n        </div>\r\n        <section *ngIf=\"formGroup.value.type === 'scenes'\">\r\n            <label>订阅场景 <select multiple [(ngModel)]=\"notification.sceneIds\" [ngModelOptions]=\"{standalone:true}\"><option *ngFor=\"let id of ['V1','V2','V3','V4','V5','V6','V7','T1']\" [value]=\"id\">{{id}}</option></select></label>\r\n            <label>通知阶段 <select multiple [(ngModel)]=\"notification.scenePhases\" [ngModelOptions]=\"{standalone:true}\"><option value=\"candidate\">候选产生（未判定）</option><option value=\"review\">最终复核结果</option></select></label>\r\n            <label>事件子类型 <input formControlName=\"sceneKindsText\" placeholder=\"留空为全部；多个类型用英文逗号分隔\"></label>\r\n            <p *ngIf=\"sceneSubscriptionInvalid()\">至少选择一个场景和一个阶段，子类型最多64项。</p>\r\n            <p>填写邮箱接收地址。启用、重新启用或修改订阅范围后只处理新产生事件；每个事件的每个阶段去重，投递失败最多尝试3次。网络超时可能重复收到，请按eventId核对。子类型使用账本中的类型标识。</p>\r\n            <a routerLink=\"/scene-records\" (click)=\"onNoClick()\">查看事件与投递记录</a>\r\n        </section>\r\n        <div class=\"my-form-field block mt10\" *ngIf=\"formGroup.value.type === notificationAlarm\">\r\n            <span>{{'notification.property-mode' | translate}}</span>\r\n            <mat-select formControlName=\"mode\" style=\"width: 207px\">\r\n                <mat-option [value]=\"notificationModeAll\">{{'notification.property-mode-alarm-all' | translate}}</mat-option>\r\n                <mat-option [value]=\"notificationModeSingle\">{{'notification.property-mode-alarm-single' | translate}}</mat-option>\r\n            </mat-select>\r\n        </div>\r\n        <div class=\"my-form-field block mt10\" *ngIf=\"formGroup.value.type === notificationAlarm\">\r\n            <span>{{'notification.property-priority' | translate}}</span>\r\n            <mat-checkbox *ngFor=\"let item of alarmsType\" (change)=\"onSubscriptionChanged(item, $event.checked)\" [checked]=\"getTypeValue(item)\" style=\"margin: 7px 10px 7px 10px;\">\r\n                {{'alarm.property-' + item | translate}}\r\n            </mat-checkbox>\r\n        </div>\r\n    </div>\r\n    <div mat-dialog-actions class=\"dialog-action mt10\">\r\n        <button mat-raised-button (click)=\"onNoClick()\">{{'dlg.cancel' | translate}}</button>\r\n        <button mat-raised-button [disabled]=\"formGroup.invalid || sceneSubscriptionInvalid()\" (click)=\"onOkClick()\" color=\"primary\">{{'dlg.ok' | translate}}</button>\r\n    </div>\r\n</form>\r\n";

