module.exports = "<div>\r\n    <h1 mat-dialog-title class=\"dialog-title\" mat-dialog-draggable>{{'script.param-title' | translate}}</h1>\r\n    <mat-icon (click)=\"onNoClick()\" class=\"dialog-close-btn\">clear</mat-icon>\r\n    <div mat-dialog-content class=\"dialog-content\">\r\n        <div class=\"my-form-field block\">\r\n            <span>{{'script.param-name' | translate}}</span>\r\n            <input [(ngModel)]=\"data.name\" type=\"text\" [readonly]=\"data.readonly\" (input)=\"onCheckValue($event)\">\r\n        </div>\r\n        <div class=\"my-form-field mt10\">\r\n            <span>{{'script.param-type' | translate}}</span>\r\n            <mat-select [(value)]=\"data.type\" placeholder=\"{{'script.paramtype' | translate}}\">\r\n                <mat-option *ngFor=\"let type of paramType\" [value]=\"type\">\r\n                    {{ 'script.paramtype-' + type | translate }}\r\n                </mat-option>\r\n            </mat-select>\r\n        </div>\r\n        <div style=\"display: block; color: red; height: 22px\">\r\n            <span *ngIf=\"error\">{{error}}</span>\r\n        </div>\r\n    </div>\r\n    <div mat-dialog-actions class=\"dialog-action\">\r\n        <button mat-raised-button (click)=\"onNoClick()\">{{'dlg.cancel' | translate}}</button>\r\n        <button mat-raised-button [disabled]=\"!isValid(data.name)\" color=\"primary\" [mat-dialog-close]=\"data\">{{'dlg.ok' | translate}}</button>\r\n    </div>\r\n</div>";

